package com.bank.core;

// Deliberately NOT Serializable — represents a live service handle.
// But it is recreatable from a small region key.
public class ExchangeRateService {
    private final String region;
    private ExchangeRateService(String region) { this.region = region; }
    public static ExchangeRateService forRegion(String region) {
        return new ExchangeRateService(region);
    }
    public String region() { return region; }
}
