package com.bank.core;

import java.io.*;
import java.math.BigDecimal;

public class Account implements Serializable {
    private static final long serialVersionUID = 1L;

    private String accountId;
    private BigDecimal balance;
    private Owner owner;                               // FIX 1: serializable member

    private transient String sessionToken;             // FIX 2: transient (sensitive)
    private transient ExchangeRateService rateService; // FIX 3: rebuilt manually

    public Account(String accountId, BigDecimal balance, Owner owner,
                   String sessionToken, ExchangeRateService rateService) {
        this.accountId = accountId;
        this.balance = balance;
        this.owner = owner;
        this.sessionToken = sessionToken;
        this.rateService = rateService;
    }

    // FIX 3: serialize a safe substitute (the region key) and rebuild on read.
    private void writeObject(ObjectOutputStream out) throws IOException {
        out.defaultWriteObject();                 // normal fields + owner
        out.writeUTF(rateService.region());       // small, safe substitute
    }
    private void readObject(ObjectInputStream in)
            throws IOException, ClassNotFoundException {
        in.defaultReadObject();                   // normal fields + owner
        String region = in.readUTF();
        this.rateService = ExchangeRateService.forRegion(region); // rebuild handle
    }

    public String getAccountId() { return accountId; }
    public BigDecimal getBalance() { return balance; }
    public Owner getOwner() { return owner; }
    public String getSessionToken() { return sessionToken; }
    public ExchangeRateService getRateService() { return rateService; }
}
