package com.bank.core;

import java.io.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class NonSerializableMemberDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Owner rajesh = new Owner("Rajesh Kumar", "ABCDE1234F");
        Account account = new Account("SAV2001", new BigDecimal("1000000.00"),
                rajesh, "live-session-xyz", ExchangeRateService.forRegion("IN"));

        byte[] bytes;
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(buffer)) {
            oos.writeObject(account);
        }
        bytes = buffer.toByteArray();
        log.info(() -> "Serialized OK, length = " + bytes.length);

        Account back;
        try (ObjectInputStream ois =
                 new ObjectInputStream(new ByteArrayInputStream(bytes))) {
            back = (Account) ois.readObject();
        }
        log.info(() -> "Owner survived: " + back.getOwner().getName());
        log.warning(() -> "sessionToken after deserialize (transient) = " + back.getSessionToken());
        log.info(() -> "rateService rebuilt for region = " + back.getRateService().region());
    }
}
